import React, { useState, useEffect } from 'react';
import {
  Grid,
  Button,
  Typography,
  Card,
  InputAdornment,
  Divider
} from '@mui/material';
import PercentOutlinedIcon from '@mui/icons-material/PercentOutlined';
import InputField from '../components/input/inputField';
import { axios } from '../utils/axios';
import { useMyContext } from './provider';
import GenerateToastConfig from '../components/toast-config/GenerateToastConfig';
import useResponsive from '../hooks/useResponsive';

function Commission() {
  const [commissionValue, setCommissionValue] = useState('');
  const [taxValue, setTaxValue] = useState('');
  const { i18 } = useMyContext();
  const isMobile = useResponsive('down', 'sm');

  useEffect(() => {
    const fetchData = async () => {
      try {
        const res = await axios.get('module/settings');
        if (res.status === 200) {
          const data = res.data.data;
          setCommissionValue(data?.commission?.toString() || '');
          setTaxValue(data?.tax?.toString() || '');
        }
      } catch (err) {
        GenerateToastConfig(err?.response?.data?.message);
      }
    };
    fetchData();
  }, []);

  const handleAddCommission = async () => {
    try {
      const formData = new FormData();
      formData.append('commission', parseFloat(commissionValue));
      formData.append('tax', parseFloat(taxValue));
      const res = await axios.put(`module/settings/update`, formData);
      if (res.status === 201) {
        GenerateToastConfig('Commission & Tax Updated Successfully', 'success');
      } else {
        GenerateToastConfig(res.data.message);
      }
    } catch (err) {
      GenerateToastConfig(err?.response?.data?.message);
    }
  };

  const handleCommissionInputChange = (e) => {
    const numericInput = e.target.value.replace(/[^0-9.]/g, '');
    setCommissionValue(numericInput);
  };

  const handleTaxInputChange = (e) => {
    const numericInput = e.target.value.replace(/[^0-9.]/g, '');
    setTaxValue(numericInput);
  };

  return (
    <Card sx={{ padding: '20px 10px', margin: '30px 0px' }}>
      <Grid container sx={{ padding: '10px 0px' }}>
        <Grid container item justifyContent="space-between" alignItems="center">
          <Typography variant="h6" gutterBottom sx={{ marginLeft: 1 }}>
            {i18?.LISTINGPAGE?.COMMISSION_TAX || 'Commission & Tax'}
          </Typography>
        </Grid>
        <Grid>
          <Typography>
            {i18?.LISTINGPAGE?.ADD_DEFAULT || 'Add default commission & tax'}
          </Typography>
        </Grid>
      </Grid>

      <Divider sx={{ margin: '20px auto', backgroundColor: '#333' }} />

      <Grid container direction={isMobile ? 'column' : 'row'} spacing={2}>
        <Grid item xs={12} sm={6}>
          <InputField
            label={i18?.LISTINGPAGE?.COMMISSION || 'Commission'}
            text="commission"
            value={commissionValue}
            onChange={handleCommissionInputChange}
            type="number"
            sx={{ width: '100%' }}
            InputProps={{
              endAdornment: (
                <InputAdornment position="end">
                  <PercentOutlinedIcon />
                </InputAdornment>
              ),
              inputProps: {
                style: { textAlign: 'right' }
              }
            }}
          />
        </Grid>
        <Grid item xs={12} sm={6}>
          <InputField
            label={i18?.LISTINGPAGE?.TAX || 'Tax'}
            text="tax"
            value={taxValue}
            onChange={handleTaxInputChange}
            type="number"
            sx={{ width: '100%' }}
            InputProps={{
              endAdornment: (
                <InputAdornment position="end">
                  <PercentOutlinedIcon />
                </InputAdornment>
              ),
              inputProps: {
                style: { textAlign: 'right' }
              }
            }}
          />
        </Grid>
      </Grid>

      <Divider sx={{ margin: '20px auto', backgroundColor: '#333' }} />

      <div style={{ justifyContent: 'flex-end', display: 'flex' }}>
        <Button
          variant="contained"
          onClick={handleAddCommission}
          disabled={
            !commissionValue || commissionValue <= 0 ||
            !taxValue || taxValue <= 0
          }
        >
          {i18?.SETTINGSLIST?.UPDATE || 'Update'}
        </Button>
      </div>
    </Card>
  );
}

export default Commission;